SourceCode.Declaration:
/// <summary>
/// Batch job that deletes aged label preview attachments (document type <c>LBLPREV</c> on Work
/// records) and the staging rows that produced them. The retention window is read from
/// <c>WHSParameters</c>, so the job carries no packed state.
/// </summary>
public class AAXWHSLabelCapturePurge extends RunBaseBatch implements BatchRetryable, SysErrorMessageHelpScopeIBatchProvider
{
    #DEFINE.CurrentVersion(1)

    #DEFINE.LabelPreviewDocuTypeId('LBLPREV')
}

Method.Source:
/// <summary>
/// Indicates whether the batch job can be added to the batch journal.
/// </summary>
/// <returns>True, indicating the job can be scheduled in batch.</returns>
public boolean canGoBatchJournal()
{
    return true;
}

/// <summary>
/// Serializes the class state into a container.
/// </summary>
/// <returns>A container holding the serialized state.</returns>
public container pack()
{
    // The job carries no state beyond the version
    return [#CurrentVersion];
}

/// <summary>
/// Deserializes the class state from a container.
/// </summary>
/// <param name = "_packedClass">A container holding the serialized state.</param>
/// <returns>True if the container version is supported.</returns>
public boolean unpack(container _packedClass)
{
    boolean     ret;
    Integer     version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version] = _packedClass;
            ret = true;
            break;

        default:
            ret = false;
            break;
    }

    return ret;
}

/// <summary>
/// Deletes aged label preview attachments and their staging rows in every non-virtual company.
/// Removes only <c>LBLPREV</c> attachments and Done or Poison staging rows older than the
/// retention window, deleting each row in its own transaction.
/// </summary>
private void cleanup()
{
    // The cutoff is computed once from the retention parameter
    utcDateTime cutoff = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -WHSParameters::find().aaxPreviewRetentionDays());

    DataArea dataArea;

    while select Id from dataArea
        where !dataArea.isVirtual
    {
        changecompany(dataArea.Id)
        {
            this.purgeCompany(cutoff);
        }
    }
}

/// <summary>
/// Deletes aged <c>LBLPREV</c> attachments and Done or Poison staging rows in the current company.
/// </summary>
/// <param name = "_cutoff">Records created before this UTC timestamp are removed.</param>
private void purgeCompany(utcDateTime _cutoff)
{
    DocuRef                     docuRef;
    AAXWHSLabelCaptureStaging   staging;

    // Deleting the DocuRef also removes its DocuValue and file
    while select forupdate docuRef
        where docuRef.TypeId          == #LabelPreviewDocuTypeId
           && docuRef.RefTableId      == tableNum(WHSWorkTable)
           && docuRef.createdDateTime <  _cutoff
    {
        docuRef.delete();
    }

    // Only terminal staging rows are purged
    while select forupdate staging
        where (staging.Status == AAXWHSLabelCaptureStatus::Done
            || staging.Status == AAXWHSLabelCaptureStatus::Poison)
           && staging.createdDateTime < _cutoff
    {
        staging.delete();
    }
}

/// <summary>
/// Runs the purge inside the batch error context and retries transient errors.
/// </summary>
public void run()
{
    using (SysErrorMessageHelpScope scope = SysErrorMessageHelpScope::newErrorContextBatchServer(this))
    {
        #OCCRetryCount

        try
        {
            this.cleanup();
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::TransientSqlConnectionError)
        {
            // Retry transient connection errors up to the session retry limit
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw;
            }
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw;
            }
        }
    }
}

/// <summary>
/// Indicates whether the batch job runs impersonated as the user who scheduled it.
/// </summary>
/// <returns>True, indicating the job runs impersonated.</returns>
public boolean runsImpersonated()
{
    return true;
}

/// <summary>
/// Determines if the job can run in a new session.
/// </summary>
/// <returns>True if the job can run in a new session.</returns>
protected boolean canRunInNewSession()
{
    return true;
}

/// <summary>
/// Constructs a new instance of the <c>AAXWHSLabelCapturePurge</c> class.
/// </summary>
/// <returns>A new <c>AAXWHSLabelCapturePurge</c> instance.</returns>
static AAXWHSLabelCapturePurge construct()
{
    return new AAXWHSLabelCapturePurge();
}

/// <summary>
/// Provides a description for the batch task.
/// </summary>
/// <returns>A string description of the batch task.</returns>
static ClassDescription description()
{
    return "@AAXWarehouseTools:CapturePurgeBatch";
}

/// <summary>
/// Entry point invoked by the AAXWHSLabelCapturePurge menu item.
/// </summary>
/// <param name = "args">Framework arguments from the caller.</param>
static void main(Args args)
{
    AAXWHSLabelCapturePurge labelCapturePurge = AAXWHSLabelCapturePurge::construct();

    using (SysErrorMessageHelpScope scope = SysErrorMessageHelpScope::newErrorContextBatchController(labelCapturePurge))
    {
        if (labelCapturePurge.prompt())
        {
            labelCapturePurge.runOperation();
        }
    }
}

/// <summary>
/// Indicates whether the batch job is retryable.
/// </summary>
/// <returns>True, indicating the batch job can be retried.</returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Gets the form name used for the error context using a <c>SysErrorMessageHelpScope</c> class.
/// </summary>
/// <returns>The form name used for the error context.</returns>
[Hookable(false)]
public FormName errorMessageHelpScopeFormName()
{
    return strFmt('%1_%2', formStr(Dialog), classStr(AAXWHSLabelCapturePurge));
}

/// <summary>
/// Gets the action name used for the error context using a <c>SysErrorMessageHelpScope</c> class.
/// </summary>
/// <returns>The action name used for the error context.</returns>
[Hookable(false)]
public str errorMessageHelpScopeActionName()
{
    return menuItemActionStr(AAXWHSLabelCapturePurge);
}
